import torch
import torch_npu

_GLU_ACTIVATIONS = {"swiglu", "geglu", "reglu"}

def _apply_activation(x, activation):
    if activation == "fastgelu":
        return x * torch.sigmoid(1.7 * x)
    elif activation == "gelu":
        return torch.nn.functional.gelu(x, approximate="tanh")
    elif activation == "relu":
        return torch.nn.functional.relu(x)
    elif activation == "silu":
        return torch.nn.functional.silu(x)
    elif activation == "geglu":
        gate, up = x.chunk(2, dim=-1)
        return torch.nn.functional.gelu(gate, approximate="tanh") * up
    elif activation == "swiglu":
        gate, up = x.chunk(2, dim=-1)
        return torch.nn.functional.silu(gate) * up
    elif activation == "reglu":
        gate, up = x.chunk(2, dim=-1)
        return torch.nn.functional.relu(gate) * up
    else:
        raise ValueError(f"Unsupported activation: {activation}")

def _safe_cast(x, target_dtype):
    if x.dtype == target_dtype:
        return x
    if target_dtype == torch.float16:
        x = torch.clamp(x, -65504.0, 65504.0)
    elif target_dtype == torch.bfloat16:
        x = torch.clamp(x, -3.3895313892515355e+38, 3.3895313892515355e+38)
    return x.to(target_dtype)

def _int_matmul(a, b):
    a_f = a.to(torch.float32)
    b_f = b.to(torch.float32)
    return torch.matmul(a_f, b_f).round().to(torch.int32)

def _fallback_ffn(x, weight1, weight2, activation, expert_tokens=None, expert_tokens_index=None,
                  bias1=None, bias2=None, scale=None, offset=None,
                  deq_scale1=None, deq_scale2=None,
                  antiquant_scale1=None, antiquant_scale2=None,
                  antiquant_offset1=None, antiquant_offset2=None,
                  inner_precise=None, output_dtype=None):
    is_quant = scale is not None or deq_scale1 is not None
    is_pseudo_quant = antiquant_scale1 is not None or antiquant_scale2 is not None
    is_moe = expert_tokens is not None
    is_glu = activation in _GLU_ACTIVATIONS
    x_orig_shape = x.shape
    x_2d = x.view(-1, x.shape[-1])

    def _process_standard(x_in, w1, w2, act, b1, b2, ip, od):
        use_fp32 = (ip == 0) or is_glu
        cd = torch.float32 if use_fp32 else x_in.dtype
        xc = x_in.to(cd)
        w1c = w1.to(cd)
        w2c = w2.to(cd)
        o1 = torch.matmul(xc, w1c)
        if b1 is not None:
            o1 = o1 + b1.to(cd)
        o1 = _apply_activation(o1, act)
        o2 = torch.matmul(o1, w2c)
        if b2 is not None:
            o2 = o2 + b2.to(cd)
        if od is not None:
            out_dtype = torch.bfloat16 if od == 1 else torch.float16
        else:
            out_dtype = x_in.dtype
        o2 = _safe_cast(o2, out_dtype)
        return o2

    def _process_quant(x_in, w1, w2, act, b1, b2, sc, off, dq1, dq2, od):
        o1 = _int_matmul(x_in, w1)
        if b1 is not None:
            o1 = o1 + b1.to(torch.int32)
        o1_fp = o1.to(dq1.dtype) * dq1
        o1_act = _apply_activation(o1_fp.to(torch.float32), act) if is_glu else _apply_activation(o1_fp, act)
        sc32 = sc.to(torch.float32)
        off32 = off.to(torch.float32)
        q = torch.round(o1_act.to(torch.float32) * sc32 + off32)
        q = torch.clamp(q, -128, 127).to(torch.int8)
        o2 = _int_matmul(q, w2)
        if b2 is not None:
            o2 = o2 + b2.to(torch.int32)
        o2_fp = o2.to(dq2.dtype) * dq2
        if od is not None:
            out_dtype = torch.bfloat16 if od == 1 else torch.float16
        else:
            out_dtype = torch.float16
        o2_fp = _safe_cast(o2_fp, out_dtype)
        return o2_fp

    def _process_pseudo_quant(x_in, w1, w2, act, b1, b2, aqs1, aqs2, aqo1, aqo2, od):
        cd = torch.float32 if is_glu else x_in.dtype
        w1_fp = (w1.to(cd) + aqo1.to(cd)) * aqs1.to(cd)
        w2_fp = (w2.to(cd) + aqo2.to(cd)) * aqs2.to(cd)
        xc = x_in.to(cd)
        o1 = torch.matmul(xc, w1_fp)
        if b1 is not None:
            o1 = o1 + b1.to(cd)
        o1 = _apply_activation(o1, act)
        o2 = torch.matmul(o1, w2_fp)
        if b2 is not None:
            o2 = o2 + b2.to(cd)
        if od is not None:
            out_dtype = torch.bfloat16 if od == 1 else torch.float16
        else:
            out_dtype = x_in.dtype
        o2 = _safe_cast(o2, out_dtype)
        return o2

    if is_moe:
        etl = expert_tokens if isinstance(expert_tokens, list) else expert_tokens.tolist()
        ne = len(etl)
        out_chunks = [None] * x_2d.shape[0]
        ct = 0
        for eid in range(ne):
            nt = etl[eid]
            if nt == 0:
                continue
            xe = x_2d[ct:ct + nt]
            if is_pseudo_quant:
                oe = _process_pseudo_quant(xe, weight1[eid], weight2[eid], activation,
                    bias1[eid] if bias1 is not None else None,
                    bias2[eid] if bias2 is not None else None,
                    antiquant_scale1[eid], antiquant_scale2[eid],
                    antiquant_offset1[eid], antiquant_offset2[eid], output_dtype)
            elif is_quant:
                oe = _process_quant(xe, weight1[eid], weight2[eid], activation,
                    bias1[eid] if bias1 is not None else None,
                    bias2[eid] if bias2 is not None else None,
                    scale, offset, deq_scale1, deq_scale2, output_dtype)
            else:
                oe = _process_standard(xe, weight1[eid], weight2[eid], activation,
                    bias1[eid] if bias1 is not None else None,
                    bias2[eid] if bias2 is not None else None,
                    inner_precise, output_dtype)
            for i in range(nt):
                out_chunks[ct + i] = oe[i:i + 1]
            ct += nt
        out = torch.cat(out_chunks, dim=0)
    else:
        if is_pseudo_quant:
            out = _process_pseudo_quant(x_2d, weight1, weight2, activation, bias1, bias2,
                antiquant_scale1, antiquant_scale2, antiquant_offset1, antiquant_offset2, output_dtype)
        elif is_quant:
            out = _process_quant(x_2d, weight1, weight2, activation, bias1, bias2,
                scale, offset, deq_scale1, deq_scale2, output_dtype)
        else:
            out = _process_standard(x_2d, weight1, weight2, activation, bias1, bias2, inner_precise, output_dtype)

    out_shape = list(x_orig_shape[:-1]) + [out.shape[-1]]
    return out.view(out_shape)

def run(x, weight1, weight2, activation, expert_tokens=None, expert_tokens_index=None,
        bias1=None, bias2=None, scale=None, offset=None,
        deq_scale1=None, deq_scale2=None,
        antiquant_scale1=None, antiquant_scale2=None,
        antiquant_offset1=None, antiquant_offset2=None,
        inner_precise=None, output_dtype=None):
    kwargs = {}
    if expert_tokens is not None:
        kwargs["expert_tokens"] = expert_tokens
    if expert_tokens_index is not None:
        kwargs["expert_tokens_index"] = expert_tokens_index
    if bias1 is not None:
        kwargs["bias1"] = bias1
    if bias2 is not None:
        kwargs["bias2"] = bias2
    if scale is not None:
        kwargs["scale"] = scale
    if offset is not None:
        kwargs["offset"] = offset
    if deq_scale1 is not None:
        kwargs["deq_scale1"] = deq_scale1
    if deq_scale2 is not None:
        kwargs["deq_scale2"] = deq_scale2
    if antiquant_scale1 is not None:
        kwargs["antiquant_scale1"] = antiquant_scale1
    if antiquant_scale2 is not None:
        kwargs["antiquant_scale2"] = antiquant_scale2
    if antiquant_offset1 is not None:
        kwargs["antiquant_offset1"] = antiquant_offset1
    if antiquant_offset2 is not None:
        kwargs["antiquant_offset2"] = antiquant_offset2
    if inner_precise is not None:
        kwargs["inner_precise"] = inner_precise
    if output_dtype is not None:
        kwargs["output_dtype"] = output_dtype
    try:
        return torch_npu.npu_ffn(x, weight1, weight2, activation, **kwargs)
    except Exception:
        return _fallback_ffn(x, weight1, weight2, activation, expert_tokens, expert_tokens_index,
                            bias1, bias2, scale, offset, deq_scale1, deq_scale2,
                            antiquant_scale1, antiquant_scale2, antiquant_offset1, antiquant_offset2,
                            inner_precise, output_dtype)
